-- =====================================================================
--  INSTALLER LA MATIERE SVT DANS LE PIPELINE DE CORRECTION
--
--  OU  : Supabase, projet "pipeline de correction" (xgdaibekjmtffvkwvcge)
--  QUOI: SQL Editor > New query > coller UN BLOC > Run
--
--  Genere par scripts/apply-svt.mjs le 2026-07-27.
--  Deja applique en base par API le meme jour : ce fichier est la trace
--  reproductible, pas une action a refaire.
--
--  Contenu : 2 grilles, 6 sujets, 30 etalons, 2 gabarits de dossier.
--
--  Deux epreuves ecrites de specialite, notees sur 20 chacune :
--    svt_exercice_1 - mobiliser ses connaissances, sans dossier documentaire
--                     bareme 8 / 6 / 4 / 2
--    svt_exercice_2 - demarche scientifique a partir de documents
--                     bareme 5 / 5 / 4 / 4 / 2 (grille SKILLSVT.md a l'identique)
--
--  L'exercice 1 n'a pas de dossier documentaire : le critere "Exploitation
--  des documents" y est redistribue sur connaissances et raisonnement,
--  sinon un critere resterait toujours a zero.
--
--  Tout le texte accentue passe par convert_from(decode(...,'hex'),'UTF8') :
--  l'editeur SQL de Supabase abime l'UTF-8 colle depuis un Mac.
--  Idempotent : chaque insert est un upsert sur la cle primaire.
-- =====================================================================


-- =====================================================================
--  BLOC A - LES 2 GRILLES
-- =====================================================================

begin;

insert into public.rubrics (id, track, matiere, exercise_type, version, status, system_prompt, rubric_json)
values ('SVT_EXERCICE1_V1', 'generale', 'svt', 'svt_exercice_1', 1, 'active', convert_from(decode('','hex'),'UTF8'), convert_from(decode('','hex'),'UTF8')::jsonb)
on conflict (id) do update set
  track = excluded.track, matiere = excluded.matiere, exercise_type = excluded.exercise_type,
  version = excluded.version, status = excluded.status,
  system_prompt = excluded.system_prompt, rubric_json = excluded.rubric_json;

insert into public.rubrics (id, track, matiere, exercise_type, version, status, system_prompt, rubric_json)
values ('SVT_EXERCICE2_V1', 'generale', 'svt', 'svt_exercice_2', 1, 'active', convert_from(decode('','hex'),'UTF8'), convert_from(decode('','hex'),'UTF8')::jsonb)
on conflict (id) do update set
  track = excluded.track, matiere = excluded.matiere, exercise_type = excluded.exercise_type,
  version = excluded.version, status = excluded.status,
  system_prompt = excluded.system_prompt, rubric_json = excluded.rubric_json;

commit;


