-- =====================================================================
--  BLOC E - VERIFICATION
--  Attendu : 2 grilles (20 pts chacune), 6 sujets, 30 etalons (5 par
--  sujet), 2 gabarits.
-- =====================================================================

select 'grilles' as objet, count(*) as n from public.rubrics where matiere = 'svt' and status = 'active'
union all
select 'sujets', count(*) from public.subject_cards where matiere = 'svt' and status = 'active'
union all
select 'etalons', count(*) from public.benchmark_cards b
  join public.subject_cards s on s.id = b.subject_id where s.matiere = 'svt'
union all
select 'gabarits', count(*) from public.dossier_templates where matiere = 'svt' and status = 'active';

-- Aucun sujet ne doit avoir moins de 3 etalons (sinon la correction refuse).
select s.id, s.exercise_type, count(b.id) as etalons
from public.subject_cards s
left join public.benchmark_cards b on b.subject_id = s.id
where s.matiere = 'svt'
group by s.id, s.exercise_type
order by s.id;
